python3 -c 'import subprocess,json
names=["ai-llama-router","ai-granite","ai-qwen3","ai-ministral","ai-coder"]
p=subprocess.run(["docker","inspect"]+names,capture_output=True,text=True,timeout=15)
if p.returncode: raise RuntimeError("DOCKER_INSPECT_FAILED")
for x in json.loads(p.stdout):
 print("NAME="+x["Name"].lstrip("/")+" RUNNING="+str(x["State"]["Running"])+" HEALTH="+str(x["State"].get("Health",{}).get("Status","NA")))
s=subprocess.run(["ss","-ltn"],capture_output=True,text=True,timeout=8)
for port in (18080,18181,18182,18183,18184):
 print("LISTEN_"+str(port)+"="+str(any("127.0.0.1:"+str(port)+" " in line for line in s.stdout.splitlines())))
'
